,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(6b) 25,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"–"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Bonds and bank loans"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"200,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"259,100"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"459,100"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Share capital"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"500,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"400,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(3) 400,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"500,000"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Retained earnings, from above"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"454,150"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"310,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"454,150"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"NCI, 1 January"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(3) 260,750"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"NCI, increase for the year"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(2) 19,250"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"280,000"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Total liabilities and equity"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"1,212,400"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"1,060,000"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"1,111,800"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"1,111,800"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"1,803,500"}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The 1,111,800 of debits equals the 1,111,800 of credits, and total assets of 1,803,500 equal liabilities of 569,350 plus share capital 500,000, retained earnings 454,150 and NCI 280,000."}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Consolidated profit attributable to owners = parent's equity-method profit = 114,150"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Consolidated retained earnings = parent's equity-method retained earnings = 454,150"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"NCI = 35% × (Sub net assets 710,000 + plant uplift remaining 90,000) = 35% × 800,000 = 280,000"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The 7,000 of dividend payable left after (6e) is owed to Sub's outside shareholders, a real group liability."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"6. A parent on the cost method"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"A parent using the cost method reaches the same consolidated statements by changing two entries. Its investment still stands at 520,000, its opening retained earnings lack its share of Sub's retained profits, and its profit carries dividend income instead of the share of profit."}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Parent's 2025 profit, cost method = 114,150 − 68,250 + 32,500 = 78,400"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Conversion to equity basis at 1 Jan 2025 = 48,750 − 26,000 = 22,750"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Parent's retained earnings, 1 Jan 2025, cost method = 400,000 − 22,750 = 377,250"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Worksheet entry"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Cost-method parent"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Equity-method parent"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(0) Convert opening balances"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Dr Investment in Sub 22,750 / Cr Retained earnings 1 Jan, parent 22,750"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"not needed"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(1)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Dr Dividend income 32,500 / Cr Dividends declared 32,500"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Dr Income from Sub 68,250 / Cr Dividends declared 32,500; Cr Investment in Sub 35,750"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(2) to (6)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"identical"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"identical"}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Entry (0) lifts the investment to 520,000 + 22,750 = 542,750, the opening balance entry (3) eliminates, and lifts the parent's opening retained earnings to the equity-method 400,000. The 22,750 is the parent's share of Sub's retained profits since acquisition, 65% × (250,000 − 200,000) = 32,500, less its share of the excess already written off, 65% × 15,000 = 9,750. Entry (1) then removes only the dividend income, because the 68,250 share of profit was never in the parent's column, and the consolidated column comes out as in section 5. The notes cover only the equity method; this section follows Beams and PSAK 227."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"7. Uniform policies and reporting dates"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The worksheet adds like items only if they were measured alike and at the same date. PSAK 110 requires adjustments when a group member uses accounting policies other than the group's (B87). BRPT's policy says adjustments are made \"when necessary ... to bring their accounting policies in line with the Group's accounting policies\" (Note 3c, PDF p. 67). For example (illustration, separate from the section 5 worksheet), suppose Sub carries an office building it rents out at fair value under PSAK 240 (formerly PSAK 13, IAS 40), while the group uses the cost model. Sub bought the building on 1 January 2025 and booked a fair value gain of 3,000 at year end; the group's cost-model depreciation would be 400. Before the eliminations:"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Dr Fair value gain 3,000; Dr Depreciation 400 / Cr Investment property 3,400"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Like any adjustment to Sub's figures, its effect on profit is shared with NCI, so NCI's share of profit falls by 35% × 3,400 = 1,190."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Reporting dates should be the same. If that is impracticable, the subsidiary's most recent statements may be used, adjusted for significant transactions or events in between, provided the gap is no more than three months and the length of periods and the gap stay the same from period to period (B92–B93). The notes state the same three-month limit but only require material intervening events to be disclosed; PSAK 110 requires adjustment. For example (illustration), if Sub's year ended on 30 September and the parent lent it 10,000 on 15 November, Sub's statements would show no loan while the parent's showed a receivable. The adjustment comes first, then the elimination."}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Adjust Sub: Dr Cash 10,000 / Cr Loan from parent 10,000"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Eliminate: Dr Loan from parent 10,000 / Cr Loan to Sub 10,000"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"A subsidiary with another functional currency is first translated under PSAK 221 (formerly PSAK 10, IAS 21; see "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/other-comprehensive-income","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"other-comprehensive-income"},{"type":"text","text":")."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"8. Finding the error when the worksheet does not balance"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Most errors show up in the balance sheet part, where totals stop agreeing; the notes advise checking each account one by one, but testing the entries first is faster."}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Each entry balances on its own."},{"type":"text","text":" In the notes' own 2017 worksheet for Pam and Son, the equity elimination reads \"Retained earnings $50.000; Capital stock – son $250.000; Unamortized excess $150.000 / Investment in Son $360.000; Noncontrolling interest $40.000\". Debits are 450,000 and credits 400,000. Son's capital stock is 200,000; posted as written, the entry would leave the worksheet out by 50,000. The notes' worksheet itself uses 200,000."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"The investment and the subsidiary's equity accounts fall to zero."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Each reciprocal pair cancels."},{"type":"text","text":" Leave out entry (6a) in section 5 and the worksheet still balances. A loan to Sub of 5,000 survives in the consolidated column and cash is 5,000 short, an asset the group does not have in place of one it does."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"The ties hold."},{"type":"text","text":" Consolidated profit and retained earnings attributable to owners equal the parent's under the equity method, and NCI equals its share of the subsidiary's net assets at group carrying amounts."}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Check 4 catches errors that balance. The notes' Chapter 3 balance-sheet elimination one year after acquisition reads \"Capital stock $60.000; Retained earnings $20.000; Goodwill $40.000 / Investment in son $108.000; Noncontrolling interest $12.000\". It balances at 120,000, but Son's year-end retained earnings are 40,000 and goodwill on the notes' own figures is 20,000. Goodwill is overstated by 20,000 and 20,000 of Son's retained earnings survive into the consolidated column."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"9. Consolidation procedures across industries"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Groups in layers."},{"type":"text","text":" A listed holding group can consolidate sub-group by sub-group. BREN's own statements already consolidate the Star Energy companies, so BREN's NCI can enter BRPT's worksheet as part of BREN's equity. Note 1d shows the chain, with PT Barito Wind Energy held 99.99 percent \"through BREN\" and PT Nefin Solar Asset 51 percent through Barito Wind Energy (PDF p. 26). K6 works through the effective interests."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Banks and structured entities."},{"type":"text","text":" Banks consolidate securitisation vehicles and other "},{"type":"text","marks":[{"type":"italic"}],"text":"structured entities"},{"type":"text","text":", designed so that voting rights do not decide control, when the PSAK 110 control test is met; BRPT's policy also covers them (Note 3c, PDF p. 67)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Investment entities."},{"type":"text","text":" An investment entity does not consolidate its investees, except subsidiaries that provide services for its investment activities, and measures them at fair value through profit or loss (PSAK 110 paras. 31–32)."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Mining and oil and gas."},{"type":"text","text":" A participating interest held under a joint operating agreement is usually a joint operation under PSAK 111 (formerly PSAK 66, IFRS 11), and without joint control is still recognised line by line (para. 23), so there is no investment to eliminate and no NCI."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Islamic finance."},{"type":"text","text":" A sharia subsidiary of a conventional bank is consolidated with the same entries, but it reports under PSAK 401 (formerly PSAK 101) with accounts such as murabahah receivables and temporary "},{"type":"text","marks":[{"type":"italic"}],"text":"syirkah"},{"type":"text","text":" funds, which must be mapped to the group's chart of accounts first (STANDARD — NOT VERIFIED)."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"10. Presentation and analysis: Barito Pacific's Notes 1d, 34 and 46"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Three BRPT notes show the worksheet's outputs. Note 34 splits NCI by sub-group and gives BREN's summarised figures \"before intragroup eliminations\" (PDF pp. 220–222). BREN's own consolidated statements give the equity those figures come from (BREN FS 2025, statement of financial position, PDF p. 12)."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"31 Dec 2025"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"31 Dec 2024"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"BREN equity attributable to its owners (BREN FS)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"636,868"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"516,862"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Outside share of BREN's outstanding shares (net of treasury)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"35.33114%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"35.3340%"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Outside share × equity attributable"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"225,013"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"182,628"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Add BREN's own NCI (BREN FS)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"246,651"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"215,671"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Expected NCI for \"BREN and its subsidiaries\""}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"471,664"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"398,299"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Reported in BRPT Note 34"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"471,951"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"397,199"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Difference"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"287"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"(1,100)"}]}]}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Outside share 2025 = 1 − 86,514,146,666 / (133,786,220,000 − 6,000,000 treasury) = 35.33114%; 2024, with no treasury shares = 1 − 86,514,146,666 / 133,786,220,000 = 35.3340% (BREN FS 2025, Note 19a, PDF p. 114)"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"With no fair value excess at BRPT's level, NCI should be the outside share of BREN's book equity plus BREN's own NCI, which is what entry (3) and the NCI roll-forward produce. The reported figure is within about 0.1 percent of that prediction in 2025 and 0.3 percent in 2024. The residuals are unexplained; BRPT does not reconcile them."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The segment note shows elimination at work on income (Note 46, PDF p. 239). Inter-segment revenue of 4,538 in 2025 (property 4,505 and others 33) is removed to reach consolidated revenue of 7,630,662, against 5,136 in 2024. The energy and resources segment's assets of 3,867,410 equal BREN's total assets, so the segment is BREN's consolidated statements. The eliminations column also adds 139,079 to assets and 9,339 to depreciation in 2025 (150,683 and 8,897 in 2024). Adjustments booked in no segment's ledger and depreciated each year behave like entries (4) and (5), but BRPT does not say what they are, and with no excess on BREN they may relate to another acquisition or to other group-level adjustments."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"11. Related essays"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/non-controlling-interest","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"non-controlling-interest"},{"type":"text","text":": control, NCI measurement, attribution, ownership changes."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/long-term-investments","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"long-term-investments"},{"type":"text","text":": the equity method in an investor's books."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/intangible-assets-net","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"intangible-assets-net"},{"type":"text","text":": goodwill after acquisition and its impairment."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/other-comprehensive-income","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"other-comprehensive-income"},{"type":"text","text":": translation of foreign subsidiaries before consolidation."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/retained-earnings","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"retained-earnings"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/fsli/share-capital","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"other-equity-component"},{"type":"text","text":": what consolidated retained earnings and NCI-transaction reserves contain."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/consolidation/business-combinations-acquisition-method-goodwill-common-control","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"K1"},{"type":"text","text":": the acquisition method, the allocation of excess, deferred tax on uplifts, and common control."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/consolidation/intercompany-profit-in-inventory","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"K3"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/consolidation/intercompany-profit-plant-assets","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"K4"},{"type":"text","text":": the intragroup profit entries."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/consolidation/consolidated-cash-flows-and-mid-year-acquisitions","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"K5"},{"type":"text","text":": the consolidated cash flow statement (the second half of AKL Chapter 4) and mid-year acquisitions."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/accounting/consolidation/mutual-holdings-complex-group-structures","target":"_blank","rel":"noopener noreferrer nofollow","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null}}],"text":"K6"},{"type":"text","text":": layered and mutual holdings."}]}]}]},{"type":"heading","attrs":{"textAlign":null,"level":3},"content":[{"type":"text","text":"Least-confident assertions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The NCI residuals in section 10 (287 in 2025, (1,100) in 2024) are unexplained. They are too large for rounding of the ownership percentage, and BREN's 2025 treasury shares (6,000,000, 0.01 percent) are already in the computation. Separately, Note 34 gives BREN's 2024 total assets as 3,798,375, liabilities as 3,062,313 and profit as 158,612, while BREN's own audited 2024 figures, unchanged as comparatives in its 2025 FS and used in BRPT's Note 1d and 2024 segment note (Note 46, PDF p. 239), are 3,787,513, 3,054,980 and 155,083. The net-asset gap equals the profit gap (3,529), and BREN's 2025 FS have no restatement note. CAP's 2024 total assets differ in the same way between Note 1d (5,663,616, PDF p. 24) and Note 34 (5,658,866, PDF p. 221), which suggests Note 34's 2024 summaries were compiled from different, perhaps preliminary, figures. That is inference."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The eliminations column in Note 46 (assets +139,079, depreciation +9,339) is described as behaving like an amortising consolidation adjustment. BRPT's acquisition of BREN's predecessor was accounted for under common control (Note 1d), so the adjustment probably relates to another acquisition or to something other than an excess; the FS do not say."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The Indonesian PSAK 227 text itself was not opened; paras. 10 and 12 were checked against the IAS 27 text."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The Islamic-finance mapping step in section 9 rests on knowledge of PSAK 401's presentation, not on a checked rule for consolidation."}]}]}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"References"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"PT Barito Pacific Tbk dan Entitas Anak, consolidated financial statements 31 December 2025 (audited, USD thousand): Note 1d (PDF pp. 24, 26, 52); Note 3c (PDF pp. 67–68); Note 3e (PDF p. 70); Note 34 (PDF pp. 220–222); Note 46 (PDF p. 239). BRPT FS. PDF pages verified against the PDF text layer."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"PT Barito Renewables Energy Tbk dan Entitas Anak, consolidated financial statements 31 December 2025 and 2024 (audited, USD thousand) (statement of financial position PDF p. 12; Note 19a–b, PDF pp. 114–115) and BREN FS 2024. BRPT FS (subsidiary)."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Lecture notes this page follows, \"AKL – Chapter 4 – Consolidation Technique and Procedurs\" and \"AKL – Chapter 3 – A introduction to Consolidated Financial Statements\" (Rumpun Akuntansi Keuangan), summarising Beams et al., "},{"type":"text","marks":[{"type":"italic"}],"text":"Advanced Accounting"},{"type":"text","text":". NOTES. Order followed: equity-method parent, entries (1)–(6), year of acquisition, later year, locating errors, allocation of excess; reporting dates from Chapter 3. Corrections made here, checked against the PDFs: Chapter 4 gives Son's 2016 net income as \"$46.000\" while its worksheet shows 50,000 (46,000 is profit after the 4,000 patent amortisation, and 20% × 46,000 = 9,200 is the NCI share); the 2017 entry credits \"Income from Son $20.800\" where it should credit Investment in Son; the investment is \"$209.000\" in the text and 209,600 in the schedule; Son's 2017 income is \"$600.000\" for 60,000; the equipment adjustment is written \"$2.0000\"; the 2017 equity elimination debits \"Capital stock – son $250.000\" for 200,000, so it does not balance; the Pam–Son 2017 retained earnings section ends Son's balance at 130,000 where 50,000 + 60,000 − 20,000 = 90,000 (its balance sheet shows 90,000); the fair value table is headed \"Inventories | Book Value\" for \"Fair value | Book value\"; and the worksheet is headed \"Pop 80% Son\" in a 90 percent case. Chapter 3's year-later entry (Retained earnings 20,000; Goodwill 40,000) should be 40,000 and 20,000, as already noted in essay 25. The notes measure NCI from the implied value of the parent's price (US GAAP full goodwill); PSAK 103 uses NCI's own fair value or the proportionate share, and this page uses the proportionate share. The notes cover only the equity method, and their three-month rule only requires disclosure of intervening events; section 6 follows Beams and PSAK 227, section 7 PSAK 110 B87, B92–B93. Section 9 has no note."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"PSAK 110 "},{"type":"text","marks":[{"type":"italic"}],"text":"Laporan Keuangan Konsolidasian"},{"type":"text","text":" (IFRS 10): B86, B87, B88, B92, B93 VERIFIED (web, IFRS 10 text in Commission Regulation (EU) No 1254/2012, EUR-Lex); paras. 31–32 VERIFIED in the Long-Term Investments essay (EU Regulation 2016/1703)."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"PSAK 227 "},{"type":"text","marks":[{"type":"italic"}],"text":"Laporan Keuangan Tersendiri"},{"type":"text","text":" (IAS 27), paras. 10 and 12: VERIFIED (web, IAS 27 as amended in Commission Regulation (EU) 2015/2441, checked by the independent recheck; BDO IFR Bulletin 2014/14). Amendment to PSAK 4 permitting the equity method, ratified 18 November 2015, effective for periods from 1 January 2016: VERIFIED (web, IAI exposure draft 7 Sep 2015; Binus accounting summary)."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"PSAK 103 (IFRS 3) para. 19 NCI measurement choice: VERIFIED in essay 25. PSAK 111 (para. 23), 201, 221, 240, 401: numbers from the IAI renumbering rule and list; content STANDARD — NOT VERIFIED."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Beams, Anthony, Bettinghaus and Smith, "},{"type":"text","marks":[{"type":"italic"}],"text":"Advanced Accounting"},{"type":"text","text":", chs. 3–4, the textbook the notes summarise. Not on disk; NOT VERIFIED."}]}]}]}]}$j$::jsonb
