pe":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"2.619"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"62.859"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"62.859"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"4.463"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"2.805"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"70.128"}]}]}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Current service cost, year 1 = 2.80510 / 1.071^4 = 2.132"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Closing DBO, year 1 = 21 × 2.80510 / 1.071^4 = 44.772 = 39.814 + 2.827 + 2.132"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Service cost rises each year although the unit is the same, because it is discounted over a shorter period. The DBO uses the "},{"type":"text","marks":[{"type":"italic"}],"text":"final"},{"type":"text","text":" salary, which is what \"projected\" means. An actuary does the same for thousands of employees with probabilities of death, disability and resignation at each age (PHE cites Indonesian Mortality Table IV)."}]},{"type":"heading","attrs":{"textAlign":null,"level":2},"content":[{"type":"text","text":"5. Plan assets, the net liability and the three components of cost"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"italic"}],"text":"Plan assets"},{"type":"text","text":" are assets held by a separate fund, or qualifying insurance policies, available only to pay employee benefits and not to the employer's creditors (para. 8). They are measured at fair value and netted against the DBO."}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Net defined benefit liability = DBO − fair value of plan assets (adjusted for the asset ceiling)"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The cost for the period has three components, and the standard sends each to a different place (para. 120)."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Component"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Contents"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Where"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Service cost"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"current service cost, past service cost, settlement gains and losses"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"profit or loss"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Net interest"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"discount rate × net liability (the opening balance when cash flows fall at the year end, as here)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"profit or loss"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Remeasurements"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"actuarial gains and losses on the DBO; return on plan assets excluding interest income; change in the asset ceiling"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"other comprehensive income, never reclassified (para. 122)"}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Net interest applies the same discount rate to the DBO and the plan assets (para. 123), so a company cannot report a high expected return on risky assets as profit; whatever the fund earns above or below that rate is a remeasurement."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Kieso tracks this with a "},{"type":"text","marks":[{"type":"italic"}],"text":"pension worksheet"},{"type":"text","text":", with journal columns on the left and memo columns for the DBO and plan assets on the right. For example, take PHE's 2024 opening DBO of 635,792 and plan assets of 329,152 as the starting point (Note 25b, Daftar 5/122, PDF p. 139). Assume for illustration a single discount rate of 7.1 percent, current service cost of 19,285 (PHE's reported figure), employer contributions of 74,643, benefits of 30,400 paid out of the fund (PHE's DBO movement; its asset movement shows 31,410), all cash flows at the year end, no exchange differences, and closing measurements by the actuary of 657,210 and 387,381."}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Interest cost = 635,792 × 7.1% = 45,141.2; interest income = 329,152 × 7.1% = 23,369.8"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Net interest = (635,792 − 329,152) × 7.1% = 306,640 × 7.1% = 21,771.4"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Expected DBO = 635,792 + 19,285 + 45,141.2 − 30,400 = 669,818.2; actual 657,210; actuarial gain = 12,608.2"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Expected plan assets = 329,152 + 23,369.8 + 74,643 − 30,400 = 396,764.8; actual 387,381; return below interest = 9,383.8"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Net remeasurement = 12,608.2 − 9,383.8 = 3,224.4 gain"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Item"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Expense (P&L)"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"OCI"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Cash"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Net liability"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"DBO (memo)"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Plan assets (memo)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Opening"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":nu